1-{
2-  config,
3-  pkgs,
4-  inputs,
5-  lib,
6-  ...
7-}:
8-
9-{
10-  imports = [ ./common.nix ];
11-
12-  options.cosmo.antigravity.enable = lib.mkOption {
13-    type = lib.types.bool;
14-    default = false;
15-    description = ''
16-      Whether to install the native (non-FHS) Antigravity IDE
17-      (pkgs.antigravity-ide, autoPatchelf-based) and the antigravity CLI
18-      (pkgs.antigravity-cli). Unfree; requires
19-      nixpkgs.config.allowUnfree on the host.
20-    '';
21-  };
22-
23:  options.cosmo.klaus.enable = lib.mkOption {
24-    type = lib.types.bool;
25-    default = true;
26-    description = ''
27-      Whether to enable the klaus multi-agent orchestrator and its dependencies (like claude-code).
28-    '';
--
73-    # Development Tools
74-    home.packages =
75-      with pkgs;
76-      [
77-        # Language Servers & Runtimes
78-        nixd # Nix LSP
79-        python3
80-        nodejs
81-
82-        # Build Tools
83-        gnumake
84-        gcc
85-        openssl
86-
87-        # CLIs
88-        github-cli # GitHub CLI (gh)
89-        jujutsu # Modern VCS (jj)
90-        difftastic # Structural diff (difft), wired to the `git dft` alias below
91-
92-        # Age tools
93-        inputs.agenix.packages."${pkgs.stdenv.hostPlatform.system}".default
94-
95-        # the valley CLI (S1 integrator verbs: pending/review); ships from the engine repo
96-        inputs.the-valley.packages."${pkgs.stdenv.hostPlatform.system}".valley
97-      ]
98:      ++ lib.optionals config.cosmo.klaus.enable [
99-        claude-code # Anthropic's CLI
100-
101-        # Agent orchestration (integration tests fail inside macOS build sandboxes)
102-        (inputs.klaus.packages."${pkgs.stdenv.hostPlatform.system}".default.overrideAttrs (oldAttrs: {
103-          doCheck = false;
--
106-      ++ lib.optionals config.cosmo.antigravity.enable [
107-        pkgs.antigravity-ide
108-        pkgs.antigravity-cli
109-      ];
110-
111-    programs.zsh.shellAliases = {
112-      rebuild = "if [ -e /etc/NIXOS ]; then sudo nixos-rebuild switch --flake .; else nix run home-manager -- switch --flake .; fi";
113-    };
114-
115-    # Delta as git's pager for diff/log/show (home-manager's first-class
116-    # module; programs.git.delta was renamed to programs.delta upstream).
117-    programs.delta = {
118-      enable = true;
119-      enableGitIntegration = true;
120-      options = {
121-        navigate = true; # n/N jump between files in a diff
122-        line-numbers = true;
123-      };
124-    };
125-
126-    # Structural second-opinion diff: `git dft` runs difftastic on demand
127-    # without making it the default differ.
128-    programs.git.settings.alias.dft = "-c diff.external=difft diff";
129-
130-    # Klaus agent orchestration config
131:    home.file.".klaus/config.json" = lib.mkIf config.cosmo.klaus.enable {
132-      text = builtins.toJSON {
133-        worktree_base = "/tmp/klaus-sessions";
134-        clone_base = "${config.home.homeDirectory}/hack";
135-        default_budget = "5.00";
136-        data_ref = "refs/klaus/data";

